import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class GolemClient {
    public static final BlockPos Q=new BlockPos(232,205,8);static int ticks,stage;static long due;static WorkerGolem g;static SealEntity source,dest;static ChestBlockEntity in,out;static LivingEntity victim;static GolemBuilder builder;static GolemDesign design;static int paused;static boolean denyBreak,denialProved;
    static SealEntity seal(ServerPlayer p,SealKind k,BlockPos at){return GolemProbe.seal(p,k,at);}
    static SealEntity chestSeal(ServerPlayer p,SealKind k,BlockPos chest){var l=p.level();l.setBlockAndUpdate(chest,Blocks.CHEST.defaultBlockState());var at=chest.west();l.setBlockAndUpdate(at,GolemContent.SEALS.get(k).get().defaultBlockState().setValue(SealBlock.FACING,Direction.WEST));var s=(SealEntity)l.getBlockEntity(at);s.claimOwner(p);return s;}
    static int count(ChestBlockEntity c,Item item){int n=0;for(int i=0;i<c.getContainerSize();i++)if(c.getItem(i).is(item))n+=c.getItem(i).getCount();return n;}
    static void remove(SealEntity s){if(s!=null&&s.getLevel()!=null)s.getLevel().removeBlock(s.getBlockPos(),false);}
    static WorkerGolem spawn(ServerPlayer p,GolemDesign d,BlockPos at){var l=p.level();var s=GolemContent.item(d);p.setItemInHand(InteractionHand.MAIN_HAND,s);var result=s.getItem().useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at.below()),Direction.UP,at.below(),false)));check(result==InteractionResult.SUCCESS&&s.isEmpty(),"Native golem deployment did not consume placer");return l.getEntitiesOfClass(WorkerGolem.class,new AABB(at).inflate(1)).stream().filter(x->x.ownerId().equals(p.getUUID())).findFirst().orElseThrow();}
    @SubscribeEvent public static void deny(net.minecraftforge.event.level.BlockEvent.BreakEvent e){if(System.getProperty("thaumcraft.thaumaturgyProbe","").equals("golem-client")&&denyBreak&&e.getPos().equals(Q.east(4)))e.setResult(net.minecraftforge.common.util.Result.DENY);}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post event){if(!System.getProperty("thaumcraft.thaumaturgyProbe","").equals("golem-client")||event.server().isDedicatedServer()||event.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=event.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
        if(stage==0){knowledge(p);for(var mat:java.util.Map.of("IRON",new ItemStack(Items.IRON_INGOT),"BRASS",item("plate_brass"),"THAUMIUM",item("plate_thaumium"),"VOID",item("plate_void")).entrySet()){thaumcraft.research.ScanningService.observe(p,mat.getValue());check(thaumcraft.research.ResearchService.state(p).flags().contains("f_MAT"+mat.getKey()),"Material study unavailable: "+mat.getKey());}check(thaumcraft.alchemy.AspectResolver.item(l,new ItemStack(Items.TRIPWIRE_HOOK)).getOrDefault("machina",0)==5,"Machina survival source unavailable");p.setGameMode(GameType.SURVIVAL);for(int x=13;x<=16;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);for(var q:BlockPos.betweenClosed(Q.offset(-12,0,-10),Q.offset(16,6,10)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(-12,-1,-10),Q.offset(16,-1,10)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());for(var worker:l.getEntitiesOfClass(WorkerGolem.class,new AABB(Q).inflate(40)))worker.discard();for(var drop:l.getEntitiesOfClass(ItemEntity.class,new AABB(Q).inflate(40)))drop.discard();p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-5.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);l.setBlockAndUpdate(Q,GolemContent.BUILDER.get().defaultBlockState());builder=(GolemBuilder)l.getBlockEntity(Q);p.setPos(Q.getX()+.5,Q.getY()+1,Q.getZ()+.5);builder.draft=GolemDesign.BASIC;GolemProbe.giveComponents(p,builder.draft);check(builder.start(p),"Client press payment failed");l.setBlockAndUpdate(Q.west(),thaumcraft.essentia.EssentiaContent.TUBES.get("tube").get().defaultBlockState());var jarAt=Q.west().below();l.setBlockAndUpdate(jarAt,thaumcraft.alchemy.AlchemyContent.JAR.get().defaultBlockState());var jar=(thaumcraft.alchemy.AlchemyMachine)l.getBlockEntity(jarAt);check(jar.insertEssence("machina",builder.total(),false),"Cannot fill adjacent Machina jar");p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-5.5,Set.of(),0,0,true);stage=1;due=now+160;return;}
        if(stage==1){check(now<due,"Press did not pull native essentia");if(builder.working())return;check(builder.output.getItem(0).get(GolemContent.DESIGN.get()).equals(GolemDesign.BASIC),"Press output lost design");builder.output.clearContent();design=new GolemDesign(0,0,0,3);g=spawn(p,design,Q.east(2));check(thaumcraft.thaumaturgy.SpellEngine.protectedTarget(p,g),"Owner spells/turrets do not protect golem");source=seal(p,SealKind.PICKUP,Q.offset(4,0,2));dest=chestSeal(p,SealKind.FILL,Q.east(10));out=(ChestBlockEntity)l.getBlockEntity(Q.east(10));var named=new ItemStack(Items.EMERALD,17);named.set(DataComponents.CUSTOM_NAME,Component.literal("Physical parcel"));source.filter=named.copyWithCount(1);dest.filter=source.filter.copy();l.addFreshEntity(new ItemEntity(l,Q.getX()+4.5,Q.getY()+.1,Q.getZ()+.5,named));stage=2;due=now+480;Thaumcraft.LOGGER.info("GOLEM_PRESS_OK: real Machina network and native physical deployment");return;}
        if(stage==2){check(now<due,"Pickup/delivery timed out; golem="+g.position()+" cargo="+g.cargo.getItem(0));if(count(out,Items.EMERALD)!=17)return;check(g.cargo.isEmpty()&&out.getItem(0).getHoverName().getString().equals("Physical parcel"),"Physical named cargo changed");remove(source);dest.filter=ItemStack.EMPTY;source=chestSeal(p,SealKind.EMPTY,Q.west(6));in=(ChestBlockEntity)l.getBlockEntity(Q.west(6));in.setItem(0,new ItemStack(Items.DIAMOND,23));source.channel=3;dest.channel=3;g.setChannel(3);l.setBlockAndUpdate(source.getBlockPos().south(),Blocks.REDSTONE_BLOCK.defaultBlockState());paused=count(out,Items.DIAMOND);stage=3;due=now+50;Thaumcraft.LOGGER.info("GOLEM_PICKUP_OK: actual walking, exact filter, 17 named physical items delivered");return;}
        if(stage==3&&now>=due){check(count(in,Items.DIAMOND)==23&&count(out,Items.DIAMOND)==paused,"Powered seal extracted cargo");l.removeBlock(source.getBlockPos().south(),false);stage=4;due=now+700;return;}
        if(stage==4){check(now<due,"Inventory route timed out; golem="+g.position()+" cargo="+g.cargo.getItem(0));if(count(out,Items.DIAMOND)!=23)return;check(count(in,Items.DIAMOND)==0&&g.cargo.isEmpty(),"Inventory transfer duplicated/lost items");remove(source);remove(dest);g.discard();g=spawn(p,new GolemDesign(3,0,1,3),Q.east(2));source=seal(p,SealKind.HARVEST,Q.offset(4,0,2));var cropAt=Q.east(4);l.setBlockAndUpdate(cropAt.below(),Blocks.FARMLAND.defaultBlockState());l.setBlockAndUpdate(cropAt,((CropBlock)Blocks.WHEAT).getStateForAge(7));stage=5;due=now+240;Thaumcraft.LOGGER.info("GOLEM_ROUTE_OK: native sided extraction/delivery, 23 items conserved, channels and redstone");return;}
        if(stage==5){check(now<due,"Harvest timed out; golem="+g.position());var cropAt=Q.east(4);if(l.getBlockState(cropAt).getValue(CropBlock.AGE)==7)return;check(l.getBlockState(cropAt).is(Blocks.WHEAT)&&!g.cargo.isEmpty(),"Harvest failed replant or cargo");remove(source);g.dropCargo(l);g.discard();g=spawn(p,new GolemDesign(1,0,3,0),Q.east(2));var at=Q.east(4);source=seal(p,SealKind.BREAKER,at.above());l.setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());denyBreak=true;stage=6;due=now+60;Thaumcraft.LOGGER.info("GOLEM_HARVEST_OK: mature crop harvested, actual seed reserved, crop replanted and cargo stored");return;}
        if(stage==6){if(!denialProved){if(now<due)return;check(l.getBlockState(Q.east(4)).is(Blocks.STONE)&&g.cargo.isEmpty(),"Canceled break changed block or created loot");denialProved=true;denyBreak=false;due=now+240;return;}check(now<due,"Breaker timed out; golem="+g.position());if(!l.isEmptyBlock(Q.east(4)))return;check(g.cargo.getItem(0).is(Items.COBBLESTONE),"Breaker used wrong tool loot");remove(source);g.dropCargo(l);g.discard();g=spawn(p,new GolemDesign(1,0,0,2),Q.east(2));source=seal(p,SealKind.GUARD,Q.offset(4,0,2));victim=BatRiftClient.mob(p,Vec3.atBottomCenterOf(Q.east(5)));stage=7;due=now+240;Thaumcraft.LOGGER.info("GOLEM_BREAKER_OK: native permissions/event and iron-pickaxe stone loot");return;}
        if(stage==7){check(now<due,"Guard timed out; golem="+g.position());if(victim.getHealth()>=20)return;check(victim.getHealth()<20,"Guard failed actual damage");victim.discard();remove(source);g.cargo.setItem(0,new ItemStack(Items.GOLD_INGOT,11));g.setHealth(4);g.setCustomName(Component.literal("Packed guardian"));p.setItemInHand(InteractionHand.MAIN_HAND,item("golem_bell"));check(g.interact(p,InteractionHand.MAIN_HAND,Vec3.ZERO)==InteractionResult.SUCCESS&&g.mode()==1,"Bell follow command failed");check(g.interact(p,InteractionHand.MAIN_HAND,Vec3.ZERO)==InteractionResult.SUCCESS&&g.mode()==2,"Bell stay command failed");p.setShiftKeyDown(true);check(g.interact(p,InteractionHand.MAIN_HAND,Vec3.ZERO)==InteractionResult.SUCCESS&&g.isRemoved(),"Bell packing failed");p.setShiftKeyDown(false);var pack=java.util.stream.IntStream.range(0,36).mapToObj(i->p.getInventory().getItem(i)).filter(s->s.getItem() instanceof GolemPlacer).findFirst().orElseThrow();check(pack.get(GolemContent.DESIGN.get()).equals(new GolemDesign(1,0,0,2))&&Math.abs(pack.get(GolemContent.HEALTH.get())-.2F)<.001&&pack.getHoverName().getString().equals("Packed guardian"),"Packing healed or lost design/name");check(l.getEntitiesOfClass(ItemEntity.class,new AABB(g.blockPosition()).inflate(3),x->x.getItem().is(Items.GOLD_INGOT)&&x.getItem().getCount()==11).size()==1,"Packed cargo duplicated or lost");stage=8;Thaumcraft.LOGGER.info("GOLEM_CLIENT_OK: guard damage, all six tasks, packed health/name/design and physical cargo conserved");p.teleportTo(l,Q.getX()+.5,Q.getY()+1,Q.getZ()+.5,Set.of(),0,0,true);p.openMenu(builder);}
        if(stage==8&&p.containerMenu instanceof net.minecraft.world.inventory.InventoryMenu){source=seal(p,SealKind.PICKUP,Q.north(3));source.channel=7;source.priority=2;source.radius=5;source.filter=new ItemStack(Items.DIAMOND);p.openMenu(source);stage=9;}
    }
}
